import styles from "./index.module.scss";

const StatusIcon = () => {
  return (
    <svg
      width="12"
      height="18"
      viewBox="0 0 12 18"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M6 9C6 10.6569 4.65685 12 3 12C1.34315 12 0 10.6569 0 9C0 7.34315 1.34315 6 3 6C4.65685 6 6 7.34315 6 9Z" />
    </svg>
  );
};

const TrendingIcon = () => {
  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 20 20"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        opacity="0.4"
        d="M13.975 15.8169H6.025C5.675 15.8169 5.35834 15.5919 5.24167 15.2669L1.775 5.55853C1.5 4.78353 2.38334 4.1252 3.04167 4.6002L6.375 6.98353C6.81667 7.3002 7.45 7.10853 7.64167 6.6002L9.21667 2.4002C9.48334 1.6752 10.5083 1.6752 10.775 2.4002L12.35 6.6002C12.5417 7.11686 13.1667 7.3002 13.6167 6.98353L16.95 4.6002C17.6167 4.1252 18.4917 4.79186 18.2167 5.55853L14.75 15.2669C14.6417 15.5919 14.325 15.8169 13.975 15.8169Z"
        fill="#292D32"
      />
      <path
        d="M14.1667 18.3335H5.83333C5.49167 18.3335 5.20833 18.0502 5.20833 17.7085C5.20833 17.3668 5.49167 17.0835 5.83333 17.0835H14.1667C14.5083 17.0835 14.7917 17.3668 14.7917 17.7085C14.7917 18.0502 14.5083 18.3335 14.1667 18.3335Z"
        fill="#292D32"
      />
      <path
        d="M12.0833 12.2915H7.91667C7.575 12.2915 7.29167 12.0082 7.29167 11.6665C7.29167 11.3248 7.575 11.0415 7.91667 11.0415H12.0833C12.425 11.0415 12.7083 11.3248 12.7083 11.6665C12.7083 12.0082 12.425 12.2915 12.0833 12.2915Z"
        fill="#292D32"
      />
    </svg>
  );
};

export default function WorkFlowStatus({ status }) {
  const colors = {
    inProgress: "#007AFF",
    inTesting: "#FF9500",
    finished: "#34C759",
    comingSoon: "#8E8E93",
  };

  const inPrgress = {
    borderColor: colors.inProgress,
    color: colors.inProgress,
    fill: colors.inProgress,
  };
  const inTesting = {
    borderColor: colors.inTesting,
    color: colors.inTesting,
    fill: colors.inTesting,
  };
  const finished = {
    borderColor: colors.finished,
    color: colors.finished,
    fill: colors.finished,
  };
  const comingSoon = {
    borderColor: colors.comingSoon,
    color: colors.comingSoon,
    fill: colors.comingSoon,
  };

  return (
    <div className={`${styles.flowBadge}`}>
      {(() => {
        switch (status) {
          case "In Progress":
            return (
              <span style={inPrgress}>
                <StatusIcon /> {status}
              </span>
            );
          case "Trending":
            return (
              <span style={inTesting}>
                <TrendingIcon /> {status}
              </span>
            );
          case "Finished":
            return (
              <span style={finished}>
                <StatusIcon /> {status}
              </span>
            );
          case "Coming Soon":
            return (
              <span style={comingSoon}>
                <StatusIcon /> {status}
              </span>
            );
          default:
            return null;
        }
      })()}
    </div>
  );
}
